// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0 && withdrawAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        c.withdraw(withdrawAmount);
        uint256 balanceAfter = address(c).balance;
        assertEq(balanceAfter, balanceBefore - withdrawAmount);
    }
}
